17	class UpsampleNearestExact2dGradFloatKernel {
18	public:
19	    using DT = float;
20	
21	    __aicore__ inline void Init(GM_ADDR go, GM_ADDR si, GM_ADDR gi,
22	                                 GM_ADDR tg, AscendC::TPipe *p)
23	    {
24	        CopyTilingUpsample(&t_, tg);
25	        int32_t np = t_.nc_pairs, ohw = t_.oHW, ihw = t_.iHW;
26	        goGM_.SetGlobalBuffer((__gm__ DT *)go, (uint64_t)np * ohw);
27	        giGM_.SetGlobalBuffer((__gm__ DT *)gi, (uint64_t)np * ihw);
28	        siGM_.SetGlobalBuffer((__gm__ int32_t *)si, ohw);
29	        if ASCEND_IS_AIV {
30	            pp_ = p;
31	            pp_->InitBuffer(iq_, 1, (uint32_t)(ohw * sizeof(DT)));
32	            pp_->InitBuffer(oq_, 1, (uint32_t)(ihw * sizeof(DT)));
33	            pp_->InitBuffer(sb_, (uint32_t)(ohw * sizeof(int32_t)));
34	            pp_->InitBuffer(wb_, (uint32_t)(ihw * sizeof(float)));
35	        }
36	    }
37	
38	    __aicore__ inline void Process()
39	    {
40	        if ASCEND_IS_AIV {
41	            const int32_t ci = (int32_t)AscendC::GetBlockIdx();
42	            for (int32_t bx = ci; bx < t_.n_blocks; bx += t_.launch_blocks) {
43	                int32_t ns = bx * t_.block_nc;
44	                int32_t ne = ns + t_.block_nc;
45	                if (ne > t_.nc_pairs) ne = t_.nc_pairs;
46	                doLoadSrc(t_.oHW);
47	                for (int32_t n = ns; n < ne; ++n) doRow(n, t_.oHW, t_.iHW);
48	            }
49	        }
50	    }
51	
52	private:
53	    __aicore__ inline void doLoadSrc(int32_t ohw)
54	    {
55	        sl_ = sb_.Get<int32_t>();
56	        AscendC::DataCopyExtParams cp(1, (uint32_t)(ohw * sizeof(int32_t)), 0, 0, 0);
57	        AscendC::DataCopyPadExtParams<int32_t> pp = {false, 0, 0, 0};
58	        AscendC::DataCopyPad(sl_, siGM_[0], cp, pp);
59	        AscendC::PipeBarrier<PIPE_MTE2>();
60	    }
61	
62	    __aicore__ inline void doRow(int32_t row, int32_t ohw, int32_t ihw)
63	    {
64	        // CopyIn: GM→TQue (MTE pipeline, synchronized internally by TQue)
65	        il_ = iq_.AllocTensor<DT>();
66	        AscendC::DataCopyExtParams cpIn(1, (uint32_t)(ohw * sizeof(DT)), 0, 0, 0);
67	        AscendC::DataCopyPadExtParams<DT> ppIn = {false, 0, 0, 0};
68	        AscendC::DataCopyPad(il_, goGM_[(uint64_t)row * ohw], cpIn, ppIn);
69	        iq_.EnQue(il_);
70	        il_ = iq_.DeQue<DT>();
71	
72	        // Compute: zero-init TBuf, then vector add from TQue→TBuf
73	        wl_ = wb_.Get<float>();
74	        AscendC::Duplicate(wl_, 0.0f, ihw);
75	
76	        // Scatter-add: read from TQue LocalTensor, write to TBuf
77	        for (int32_t pos = 0; pos < ohw; ++pos) {
78	            int32_t src = sl_.GetValue(pos);
79	            float val = il_.GetValue(pos);
80	            float ov = wl_.GetValue(src);
81	            wl_.SetValue(src, ov + val);
82	        }
83	        iq_.FreeTensor(il_);
84	
85	        // CopyOut: Vector Add copies TBuf result to TQue, then TQue→GM
86	        // (avoiding FIXP DataCopy between TBuf and TQue)
87	        ol_ = oq_.AllocTensor<DT>();
88	        AscendC::Duplicate(ol_, static_cast<DT>(0), ihw);
89	        AscendC::Add(ol_, ol_, wl_, ihw);  // ol_ = 0 + wl_
90	        oq_.EnQue(ol_);
91	        ol_ = oq_.DeQue<DT>();
92	        AscendC::DataCopyExtParams cpOut(1, (uint32_t)(ihw * sizeof(DT)), 0, 0, 0);
93	        AscendC::DataCopyPad(giGM_[(uint64_t)row * ihw], ol_, cpOut);
94	        oq_.FreeTensor(ol_);
95	    }
96	
97	    UpsampleNearestExact2dGradTiling t_;
98	    AscendC::TPipe *pp_ = nullptr;
99	    AscendC::GlobalTensor<DT> goGM_, giGM_;
100	    AscendC::GlobalTensor<int32_t> siGM_;
101	    AscendC::TQue<AscendC::TPosition::VECIN, 1> iq_;
102	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> oq_;
103	    AscendC::TBuf<AscendC::TPosition::VECCALC> sb_, wb_;
104	    AscendC::LocalTensor<DT> il_, ol_;
105	    AscendC::LocalTensor<int32_t> sl_;
106	    AscendC::LocalTensor<float> wl_;
107	};
