39	at::Tensor upsample_nearest_exact2d_grad(
40	    const at::Tensor &grad_output,    // (N*C, oH*oW) float32
41	    const at::Tensor &src_indices,    // (oH*oW,) int32
42	    at::Tensor &grad_input)           // (N*C, iH*iW) float32, pre-allocated
43	{
44	    TORCH_CHECK(grad_output.dim() == 2, "grad_output must be 2D");
45	    TORCH_CHECK(src_indices.dim() == 1, "src_indices must be 1D");
46	    TORCH_CHECK(grad_input.dim() == 2, "grad_input must be 2D");
47	    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");
48	    TORCH_CHECK(src_indices.is_contiguous(), "src_indices must be contiguous");
49	    TORCH_CHECK(grad_input.is_contiguous(), "grad_input must be contiguous");
50	    TORCH_CHECK(grad_output.scalar_type() == at::kFloat, "grad_output must be float32");
51	    TORCH_CHECK(grad_input.scalar_type() == at::kFloat, "grad_input must be float32");
52	    TORCH_CHECK(src_indices.scalar_type() == at::kInt, "src_indices must be int32");
53	
54	    int64_t ncPairs = grad_output.size(0);
55	    int64_t oHW = grad_output.size(1);
56	    int64_t iHW = grad_input.size(1);
57	
58	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
59	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
60	    int64_t blockNC = 16;
61	    int64_t nBlocksVal = (ncPairs + blockNC - 1) / blockNC;
62	    int32_t usedCoreNum = static_cast<int32_t>(std::min(coreNum, nBlocksVal));
63	    if (usedCoreNum < 1) {
64	        usedCoreNum = 1;
65	    }
66	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
67	
68	    at::Tensor tilingCpu = at::empty(
69	        {static_cast<int64_t>(sizeof(UpsampleNearestExact2dGradTiling))},
70	        at::device(at::kCPU).dtype(at::kByte));
71	    auto *tilingPtr = reinterpret_cast<UpsampleNearestExact2dGradTiling *>(tilingCpu.data_ptr());
72	    PopulateTiling(tilingPtr,
73	                   static_cast<int32_t>(ncPairs),
74	                   static_cast<int32_t>(oHW),
75	                   static_cast<int32_t>(iHW),
76	                   usedCoreNum);
77	    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);
78	
79	    EXEC_KERNEL_CMD(upsample_nearest_exact2d_grad_float, blockDim,
80	                    grad_output, src_indices, grad_input, tilingNpu);
81	
82	    return grad_input;
83	}
