constexpr int32_t TILE_OHW = 128;             // oHW tile size for inner tiling

struct UpsampleBicubic2dGradTiling {
    int32_t nc_pairs;
    int32_t oHW;
    int32_t iHW;
    int32_t block_nc;         // NC pairs per logical block
    int32_t n_blocks;          // total number of blocks
    int32_t launch_blocks;     // number of cores launched
    int32_t tile_oHW;          // oHW tile size for inner tiling
    int32_t n_ohw_tiles;       // number of oHW tiles
};

#endif
