#include "kernel_operator.h"
#include "upsample_bicubic2d_grad_tiling.h"

__aicore__ inline void CopyTilingUpsampleBicubic(UpsampleBicubic2dGradTiling *t, GM_ADDR tg)
{
    int32_t *d = reinterpret_cast<int32_t *>(t);
    auto *s = reinterpret_cast<__gm__ int32_t *>(tg);
    constexpr size_t n = sizeof(UpsampleBicubic2dGradTiling) / sizeof(int32_t);
    for (size_t i = 0; i < n; ++i) { d[i] = s[i]; }
}

class UpsampleBicubic2dGradFloatKernel {
public:
    using DT = float;

    __aicore__ inline void Init(GM_ADDR go, GM_ADDR si, GM_ADDR wt, GM_ADDR gi,
                                 GM_ADDR tg, AscendC::TPipe *p)
    {
        CopyTilingUpsampleBicubic(&t_, tg);
        int32_t np = t_.nc_pairs, ohw = t_.oHW, ihw = t_.iHW;
        goGM_.SetGlobalBuffer((__gm__ DT *)go, (uint64_t)np * ohw);
        giGM_.SetGlobalBuffer((__gm__ DT *)gi, (uint64_t)np * ihw);
        siGM_.SetGlobalBuffer((__gm__ int32_t *)si, (uint64_t)ohw * BICUBIC_KERNEL_SIZE);
        wtGM_.SetGlobalBuffer((__gm__ float *)wt, (uint64_t)ohw * BICUBIC_KERNEL_SIZE);
        if ASCEND_IS_AIV {
            pp_ = p;
            constexpr int32_t tohw = TILE_OHW;
            pp_->InitBuffer(iq_, 1, (uint32_t)(tohw * sizeof(DT)));
            pp_->InitBuffer(oq_, 1, (uint32_t)(ihw * sizeof(DT)));
            pp_->InitBuffer(sb_, (uint32_t)(tohw * BICUBIC_KERNEL_SIZE * sizeof(int32_t)));
            pp_->InitBuffer(wb_, (uint32_t)(tohw * BICUBIC_KERNEL_SIZE * sizeof(float)));
            pp_->InitBuffer(gb_, (uint32_t)(ihw * sizeof(float)));
            pp_->InitBuffer(prod_b_, (uint32_t)(BICUBIC_KERNEL_SIZE * sizeof(float)));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int32_t ci = (int32_t)AscendC::GetBlockIdx();
            for (int32_t bx = ci; bx < t_.n_blocks; bx += t_.launch_blocks) {
                int32_t ns = bx * t_.block_nc;
                int32_t ne = ns + t_.block_nc;
                if (ne > t_.nc_pairs) ne = t_.nc_pairs;
                for (int32_t n = ns; n < ne; ++n) doRow(n);
            }
        }
    }

private:
    __aicore__ inline void doRow(int32_t row)
    {
        const int32_t ohw = t_.oHW;
        const int32_t ihw = t_.iHW;
