int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

void PopulateTiling(UpsampleBicubic2dGradTiling *tiling,
                    int32_t ncPairs, int32_t oHW, int32_t iHW,
                    int32_t usedCoreNum)
{
    constexpr int32_t kBlockNC = 16;
    constexpr int32_t kTileOHW = TILE_OHW;
    int32_t nBlocks = CeilDivI32(ncPairs, kBlockNC);
    int32_t nOHWTiles = CeilDivI32(oHW, kTileOHW);

    tiling->nc_pairs = ncPairs;
    tiling->oHW = oHW;
    tiling->iHW = iHW;
    tiling->block_nc = kBlockNC;
    tiling->n_blocks = nBlocks;
    tiling->launch_blocks = usedCoreNum;
    tiling->tile_oHW = kTileOHW;
    tiling->n_ohw_tiles = nOHWTiles;
}

