    TORCH_CHECK(weights.dim() == 2, "weights must be 2D");
    TORCH_CHECK(grad_input.dim() == 2, "grad_input must be 2D");
    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");
    TORCH_CHECK(src_indices.is_contiguous(), "src_indices must be contiguous");
    TORCH_CHECK(weights.is_contiguous(), "weights must be contiguous");
    TORCH_CHECK(grad_input.is_contiguous(), "grad_input must be contiguous");
    TORCH_CHECK(grad_output.scalar_type() == at::kFloat, "grad_output must be float32");
    TORCH_CHECK(grad_input.scalar_type() == at::kFloat, "grad_input must be float32");
    TORCH_CHECK(src_indices.scalar_type() == at::kInt, "src_indices must be int32");
    TORCH_CHECK(weights.scalar_type() == at::kFloat, "weights must be float32");

    int64_t ncPairs = grad_output.size(0);
    int64_t oHW = grad_output.size(1);
    int64_t iHW = grad_input.size(1);

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    int64_t blockNC = 16;
    int64_t nBlocksVal = (ncPairs + blockNC - 1) / blockNC;
    int32_t usedCoreNum = static_cast<int32_t>(std::min(coreNum, nBlocksVal));
    if (usedCoreNum < 1) {
        usedCoreNum = 1;
    }
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(UpsampleBicubic2dGradTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *tilingPtr = reinterpret_cast<UpsampleBicubic2dGradTiling *>(tilingCpu.data_ptr());
    PopulateTiling(tilingPtr,
                   static_cast<int32_t>(ncPairs),
                   static_cast<int32_t>(oHW),
                   static_cast<int32_t>(iHW),
                   usedCoreNum);

    int64_t tilingLength = static_cast<int64_t>(sizeof(UpsampleBicubic2dGradTiling));
    int64_t usedCoreNumL = static_cast<int64_t>(usedCoreNum);
    int64_t blockNCVal = 16;
    int64_t tileOHWVal = TILE_OHW;
    float dummyFloat = 0.0f;

    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);
    EXEC_KERNEL_CMD(upsample_bicubic2d_grad_float, blockDim,
                    grad_output, src_indices, weights, grad_input, tilingNpu);

    return grad_input;
}

